#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> pii;

const int N = 205;
const int M = N * N;

int read() { int x; cin >> x; return x; }

struct Edge {
    int to, rev, cap;
};

vector<Edge> g[2*N];
int level[2*N], it[2*N];

void add_edge(int u, int v, int cap) {
    g[u].push_back({v, (int)g[v].size(), cap});
    g[v].push_back({u, (int)g[u].size()-1, 0});
}

bool bfs(int s, int t) {
    fill(level, level+2*N, -1);
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto &e : g[v]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] >= 0;
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = it[v]; i < (int)g[v].size(); ++i) {
        Edge &e = g[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                g[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        fill(it, it+2*N, 0);
        while (int f = dfs(s, t, 1e9)) flow += f;
    }
    return flow;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    int n = read(), dt = read();
    vector<vector<int>> a(n, vector<int>(n));
    vector<vector<int>> b(n, vector<int>(n));
    vector<vector<bool>> red(n, vector<bool>(n, false));
    vector<vector<bool>> block(n, vector<bool>(n, false));
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            char c; cin >> c;
            if (c == 'Y') block[x][y] = true;
            else if (c == 'Z') red[x][y] = true;
            else a[x][y] = c - '0';
        }
    }
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            char c; cin >> c;
            if (c != 'Y' && c != 'Z') b[x][y] = c - '0';
        }
    }
    int m = n*n;
    vector<vector<int>> dis(m, vector<int>(m, 1e9));
    for (int i=0; i<m; ++i) dis[i][i] = 0;
    int dx[4] = {0,-1,0,1};
    int dy[4] = {1,0,-1,0};
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            if (block[x][y] || red[x][y]) continue;
            for (int d=0; d<4; ++d) {
                int i = x+dx[d], j = y+dy[d];
                if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j]) {
                    dis[x*n+y][i*n+j] = 1;
                }
            }
        }
    }
    for (int k=0; k<m; ++k)
        for (int i=0; i<m; ++i)
            for (int j=0; j<m; ++j)
                if (dis[i][k] + dis[k][j] < dis[i][j])
                    dis[i][j] = dis[i][k] + dis[k][j];
    vector<int> dred(m, 1e9);
    queue<pii> q;
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            if (red[i][j]) {
                dred[i*n+j] = 0;
                q.push({i,j});
            }
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        int x = cur.first, y = cur.second;
        for (int d=0; d<4; ++d) {
            int i = x+dx[d], j = y+dy[d];
            int id = i*n+j;
            if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j] && dred[id] > 1e9) {
                dred[id] = dred[x*n+y] + 1;
                q.push({i,j});
            }
        }
    }
    int source = 2*m, sink = 2*m+1;
    vector<bool> seen(m);
    for (int cur=0; cur<m; ++cur) {
        int sx = cur/n, sy = cur%n;
        if (block[sx][sy] || red[sx][sy]) continue;
        fill(seen.begin(), seen.end(), false);
        queue<pii> q2;
        q2.push({sx,sy});
        seen[cur] = true;
        while (!q2.empty()) {
            auto p = q2.front(); q2.pop();
            int x = p.first, y = p.second;
            int id = x*n+y;
            if (dis[cur][id] <= dt)
                add_edge(cur*2, id*2+1, 1000);
            if (dis[cur][id] == dred[id]) continue;
            for (int d=0; d<4; ++d) {
                int i = x+dx[d], j = y+dy[d];
                int nid = i*n+j;
                if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j] && dis[cur][nid] <= dred[nid] && dis[cur][nid] <= dt && dis[cur][nid] > dis[cur][id] && !seen[nid]) {
                    seen[nid] = true;
                    q2.push({i,j});
                }
            }
        }
    }
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            add_edge(source, (i*n+j)*2, a[i][j]);
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            add_edge((i*n+j)*2+1, sink, b[i][j]);
    cout << max_flow(source, sink);
    return 0;
}
